import jakarta.persistence.LockModeType;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** The sheet, locked for update until the transaction ends. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select s from Sheet s where s.id = :id")
    Optional<Sheet> findLockedById(String id);

    /** The sheets naming this one as their parent. */
    List<Sheet> findByParentIdOrderByIdAsc(String parentId);
}
package net.officefloor.hq.app.sheet;

import java.time.Clock;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Loads sheets by id; a sheet never loaded before starts empty, its today the real date. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Clock clock;
    private final Audit audit;

    public SheetService(SheetRepository sheets, Clock clock, Audit audit) {
        this.sheets = sheets;
        this.clock = clock;
        this.audit = audit;
    }

    /** The sheet with this id, created empty when it was never loaded before. */
    public Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, LocalDate.now(clock)));
            } catch (DataIntegrityViolationException e) {
                return sheets.findById(id).orElseThrow(() -> e); // created concurrently
            }
        });
    }

    /** The sheet's today: the date every date-dependent decision and default on the sheet uses. */
    public LocalDate today(String id) {
        return load(id).getToday();
    }

    /** Take the sheet's next claim number, holding the sheet locked until the transaction ends so
     *  claims opened at the same moment get different numbers. */
    @Transactional
    public long nextClaimNumber(String id) {
        load(id);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        long number = sheet.nextClaimNumber();
        sheets.saveAndFlush(sheet);
        return number;
    }

    /** Take the sheet's next settle batch number, holding the sheet locked until the transaction
     *  ends so bulk settles made at the same moment get different numbers. */
    @Transactional
    public long nextBatchNumber(String id) {
        load(id);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        long number = sheet.nextBatchNumber();
        sheets.saveAndFlush(sheet);
        return number;
    }

    /** Hold the sheet locked until the transaction ends, so changes to it made at the same moment
     *  wait their turn. */
    @Transactional
    public void lock(String id) {
        load(id);
        sheets.findLockedById(id).orElseThrow();
    }

    /** Change the sheet's today. */
    @Transactional
    public Sheet setToday(String id, LocalDate today) {
        Sheet sheet = load(id);
        sheet.setToday(today);
        return sheets.save(sheet);
    }

    /** The ids of the sheet's descendants: its children (the sheets naming it as their parent), their
     *  children, and so on; the sheet itself is not among them. */
    public List<String> descendants(String id) {
        List<String> found = new ArrayList<>();
        Set<String> seen = new HashSet<>(Set.of(id));
        List<String> next = List.of(id);
        while (!next.isEmpty()) {
            List<String> children = new ArrayList<>();
            for (String parent : next) {
                for (Sheet child : sheets.findByParentIdOrderByIdAsc(parent)) {
                    if (seen.add(child.getId())) {
                        children.add(child.getId());
                    }
                }
            }
            found.addAll(children);
            next = children;
        }
        return found;
    }

    /** The ids of the other sheets of the sheet's tree: its ancestors (its parent, the parent's parent,
     *  and so on) and its descendants, among the sheets that exist; the sheet itself is not among them. */
    public List<String> tree(String id) {
        List<String> found = new ArrayList<>();
        Set<String> seen = new HashSet<>(Set.of(id));
        for (String up = sheets.findById(id).map(Sheet::getParentId).orElse(null); up != null && seen.add(up);
                up = sheets.findById(up).map(Sheet::getParentId).orElse(null)) {
            if (sheets.existsById(up)) {
                found.add(up);
            }
        }
        for (String down : descendants(id)) {
            if (!found.contains(down)) {
                found.add(down);
            }
        }
        return found;
    }

    /** Whether the sheet is archived: every change to it is then refused. */
    public boolean isArchived(String id) {
        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
    }

    /** Archive the sheet; refused when it is archived already. */
    @Transactional
    public Sheet archive(String id, String by) {
        load(id);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        if (sheet.isArchived()) {
            throw new ArchiveRefusedException("the sheet is archived already");
        }
        sheet.archive();
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + by);
        return saved;
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The events that only report figures: they never name a delegating steward. A SNAPSHOT is not
     *  one of them: it records the user's own change of the sheet's today. */
    private static final Set<String> FIGURES_ONLY = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;
    private final ObjectProvider<SettingService> settings;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<SettingService> settings) {
        this.file = Path.of(path);
        this.settings = settings;
    }

    /**
     * The record as written: a change made by a user acting as a steward by a delegation in force on
     * the sheet's today ends with for=<the steward who delegated>; a record that only reports figures
     * does not.
     */
    private String delegated(String entry) {
        String event = entry.split(" ", 2)[0];
        int sheetAt = entry.indexOf(" sheet=");
        int byAt = entry.indexOf(" by=");
        if (FIGURES_ONLY.contains(event) || sheetAt < 0 || byAt < sheetAt) {
            return entry;
        }
        String sheetId = entry.substring(sheetAt + " sheet=".length(), byAt);
        int byEnd = entry.indexOf(' ', byAt + " by=".length());
        String by = entry.substring(byAt + " by=".length(), byEnd < 0 ? entry.length() : byEnd);
        return settings.getObject().delegatedBy(sheetId, by).map(steward -> entry + " for=" + steward).orElse(entry);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing; outside a transaction it is appended at once.
     */
    public void recordOnCommit(String change) {
        String entry = delegated(change);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** Every line the audit file holds, in the order they were appended; none when there is no file yet. */
    public synchronized List<String> lines() {
        try {
            return Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

